package com.phloots.busjam.ui.skin.critter

import android.content.Context
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.FilterQuality
import androidx.compose.ui.graphics.ImageBitmap
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.res.imageResource
import androidx.compose.ui.unit.IntOffset
import androidx.compose.ui.unit.IntSize
import com.phloots.busjam.R
import kotlin.math.roundToInt

/**
 * The chibi kitten sprites (sitting, front and right-facing), one per palette colour in [CritterPalette] order.
 * Generated by art/tools/critter_sprites.py from the kitten pack's reference views.
 */
object CritterSprites {
    private val frontIds = intArrayOf(
        R.drawable.critter_kitten_pink_front, R.drawable.critter_kitten_mint_front, R.drawable.critter_kitten_sky_front,
        R.drawable.critter_kitten_butter_front, R.drawable.critter_kitten_lavender_front, R.drawable.critter_kitten_tangerine_front,
        R.drawable.critter_kitten_cherry_front, R.drawable.critter_kitten_blueberry_front, R.drawable.critter_kitten_plum_front,
        R.drawable.critter_kitten_charcoal_front,
    )
    private val rightIds = intArrayOf(
        R.drawable.critter_kitten_pink_right, R.drawable.critter_kitten_mint_right, R.drawable.critter_kitten_sky_right,
        R.drawable.critter_kitten_butter_right, R.drawable.critter_kitten_lavender_right, R.drawable.critter_kitten_tangerine_right,
        R.drawable.critter_kitten_cherry_right, R.drawable.critter_kitten_blueberry_right, R.drawable.critter_kitten_plum_right,
        R.drawable.critter_kitten_charcoal_right,
    )

    private var front: List<ImageBitmap> = emptyList()
    private var right: List<ImageBitmap> = emptyList()

    /** Decodes the sprites once; later calls do nothing. */
    fun load(context: Context) {
        if (front.isNotEmpty()) return
        val res = context.resources
        front = frontIds.map { ImageBitmap.imageResource(res, it) }
        right = rightIds.map { ImageBitmap.imageResource(res, it) }
    }

    /** Width over height of the front view (the side view is a little wider). */
    val frontAspect: Float get() = front.firstOrNull()?.let { it.width.toFloat() / it.height } ?: 0.64f

    /**
     * Draws the kitten in palette colour [color] with its bottom centre at [base], [height] tall, facing the viewer
     * or, when [walking], to the right. Draws nothing before [load].
     */
    fun DrawScope.drawKitten(base: Offset, height: Float, color: Int, walking: Boolean, alpha: Float) {
        val set = if (walking) right else front
        if (set.isEmpty() || alpha <= 0f) return
        val img = set[color.mod(set.size)]
        val w = height * img.width / img.height
        drawImage(
            img,
            dstOffset = IntOffset((base.x - w / 2).roundToInt(), (base.y - height).roundToInt()),
            dstSize = IntSize(w.roundToInt(), height.roundToInt()),
            alpha = alpha,
            filterQuality = FilterQuality.High,
        )
    }
}
